import { render } from '@solidjs/web';
import { createSignal, createMemo, isPending, For, Loading } from 'solid-js';

const stateCities = {
  California: ['Los Angeles', 'San Francisco', 'San Diego'],
  Florida: ['Miami', 'Orlando', 'Tampa'],
  'New York': ['New York City', 'Buffalo', 'Rochester'],
  Texas: ['Houston', 'Dallas', 'Austin'],
  Utah: ['Salt Lake City', 'Provo', 'West Valley City'],
};

async function getStates() {
  await new Promise((resolve) => setTimeout(resolve, 500));
  return Object.keys(stateCities);
}

async function getCities(state) {
  await new Promise((resolve) => setTimeout(resolve, 500));
  return stateCities[state] ?? [];
}

function App() {
  const states = createMemo(getStates);
  const [selectedState, setState] = createSignal(() => states()[0]);
  const cities = createMemo(() => getCities(selectedState()));
  const [selectedCity, setCity] = createSignal('Los Angeles');

  return (
    <Loading fallback={<p>Loading...</p>}>
      <select onChange={(e) => setState(e.currentTarget.value)}>
        <For each={states()}>{(state) => <option>{state}</option>}</For>
      </select>{' '}
      <select disabled={isPending(cities)} onChange={(e) => setCity(e.currentTarget.value)}>
        <For each={cities()}>{(city) => <option>{city}</option>}</For>
      </select>
      <p>
        Selection: {selectedCity()}, {selectedState()}
      </p>
    </Loading>
  );
}

render(() => <App />, document.getElementById('app'));

